/* Collapse to icon rail on narrow viewports — no jank, just icons. */
@media (max-width: 980px) {
  :root { --sidebar-w: 64px; }
  .sidebar { padding: 14px 9px; align-items: center; }
  .brand { padding: 0 0 16px; justify-content: center; }
  .brand-text, .nav-label, .nav-badge, .status-label { display: none; }
  .nav { width: 100%; }
  .nav-item { justify-content: center; padding: 11px 0; width: 100%; }
  .nav-item.active { box-shadow: none; }
  .sidebar-footer { flex-direction: row; justify-content: center; gap: 10px; padding: 12px 0 2px; width: 100%; }
}

/* ----------------------------- Main / views ----------------------------- */

.main { flex: 1; overflow-y: auto; padding: 34px 40px 90px; min-width: 0; }
.view { display: none; max-width: 880px; margin: 0 auto; animation: viewIn 0.22s ease; }
.view.active { display: block; }
#view-interactive.active { display: flex; flex-direction: column; max-width: 1040px; min-height: calc(100vh - 130px); }

@keyframes viewIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}

.view-header h1 { margin: 0 0 6px; font-size: 24px; }
.view-header p { margin: 0 0 24px; color: var(--text-dim); max-width: 660px; }

.card {
  background: linear-gradient(180deg, var(--bg-raised), #17171a);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 20px 22px;
  margin-bottom: 16px;
  box-shadow: var(--shadow);
}
.card h2 { margin: 0 0 4px; font-size: 15px; }
.card-sub { margin: 0; color: var(--text-dim); font-size: 12.5px; }

.card-step { display: flex; gap: 13px; align-items: flex-start; margin-bottom: 16px; }
.step-num {
  width: 26px; height: 26px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  border-radius: 8px;
  background: var(--accent-soft);
  color: var(--accent-text);
  font-weight: 700; font-size: 13px;
  border: 1px solid rgba(242, 92, 26, 0.25);
}

details.collapsible summary {
  display: flex; align-items: baseline; gap: 10px;
  cursor: pointer; list-style: none; user-select: none;
}
details.collapsible summary::-webkit-details-marker { display: none; }
details.collapsible summary::before { content: "▸"; color: var(--text-faint); font-size: 12px; transition: transform var(--speed); }
details.collapsible[open] summary::before { content: "▾"; }
details.collapsible summary h2 { display: inline; }
.summary-sub { color: var(--text-faint); font-size: 12px; }
details.collapsible[open] summary { margin-bottom: 16px; }

/* ----------------------------- Forms ----------------------------- */

.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 18px; }
.field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.field.span-2 { grid-column: span 2; }
.field > span { font-size: 12px; font-weight: 600; color: var(--text-dim); }
.field > span em { font-style: normal; font-weight: 400; color: var(--text-faint); }
.field small { color: var(--text-faint); font-size: 11.5px; }

input[type="text"], input[type="password"], input[type="number"], select, textarea {
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text);
  padding: 9px 11px;
  font: inherit;
  outline: none;
  width: 100%;
  transition: border-color var(--speed), box-shadow var(--speed);
}
input:hover, select:hover, textarea:hover { border-color: var(--border-strong); }
input:focus, select:focus, textarea:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
textarea { resize: vertical; }
input::placeholder, textarea::placeholder { color: var(--text-faint); }

.checkbox { display: flex; align-items: center; gap: 7px; color: var(--text-dim); font-size: 13px; cursor: pointer; user-select: none; }
.checkbox input { width: auto; accent-color: var(--accent); }

/* ----------------------------- Buttons ----------------------------- */

.btn {
  background: var(--bg-panel);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 9px;
  padding: 8px 16px;
  font: inherit; font-weight: 600; font-size: 13px;
  cursor: pointer;
  transition: all var(--speed);
}
.btn:hover { border-color: var(--border-strong); transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn.primary {
  background: linear-gradient(180deg, var(--accent-2), var(--accent));
  border-color: rgba(255, 138, 61, 0.5);
  color: #fff;
  box-shadow: 0 2px 12px -2px var(--accent-glow);
}
.btn.primary:hover { box-shadow: 0 4px 18px -2px var(--accent-glow); filter: brightness(1.06); }
.btn.success { background: linear-gradient(180deg, #2aa569, #1d7a4b); border-color: rgba(62, 207, 142, 0.4); color: #fff; }
.btn.danger { background: linear-gradient(180deg, #b03a3e, #8f2b2e); border-color: rgba(239, 90, 95, 0.4); color: #fff; }
.btn.danger.ghost { background: transparent; border-color: var(--border); color: var(--red); }
.btn.danger.ghost:hover { border-color: var(--red); background: rgba(239, 90, 95, 0.08); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; transform: none; box-shadow: none; }
.btn.small { padding: 5px 12px; font-size: 12px; border-radius: 7px; }

.sticky-actions {
  position: sticky; bottom: 0;
  display: flex; align-items: center; gap: 12px;
  padding: 16px 0 6px;
  background: linear-gradient(transparent, var(--bg) 40%);
}
.save-note { color: var(--green); font-size: 12.5px; }
.save-note.error { color: var(--red); }

/* ----------------------------- Provider cards ----------------------------- */

.provider-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(152px, 1fr)); gap: 10px; }
.provider-card {
  position: relative;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 13px 14px;
  cursor: pointer;
  transition: all var(--speed);
}
.provider-card:hover { border-color: var(--border-strong); transform: translateY(-2px); }
.provider-card.selected {
  border-color: var(--accent);
  background: linear-gradient(180deg, var(--accent-soft), rgba(242, 92, 26, 0.04));
  box-shadow: 0 0 0 1px var(--accent), 0 4px 16px -6px var(--accent-glow);
}
.provider-card h3 { margin: 0 0 4px; font-size: 13.5px; display: flex; align-items: center; gap: 7px; flex-wrap: wrap; }
.provider-card.selected h3 { color: var(--accent-text); }
.provider-card p { margin: 0; font-size: 11.5px; color: var(--text-faint); line-height: 1.45; }
.provider-tag {
  font-size: 9px; padding: 2px 7px; border-radius: 99px;
  background: var(--bg-panel); border: 1px solid var(--border);
  color: var(--text-faint); font-weight: 600; letter-spacing: 0.4px; text-transform: uppercase;
}
.provider-card.selected .provider-tag { border-color: var(--accent-glow); color: var(--accent-text); }

/* ----------------------------- Segmented control ----------------------------- */

.seg-row { display: flex; align-items: center; gap: 14px; margin: 14px 0 16px; flex-wrap: wrap; }
.seg-label { font-size: 12px; font-weight: 600; color: var(--text-dim); }
.seg {
  display: inline-flex; gap: 3px;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 10px; padding: 3px;
}
.seg button {
  background: none; border: none; color: var(--text-dim);
  font: inherit; font-weight: 600; font-size: 12.5px;
  padding: 6px 14px; border-radius: 8px; cursor: pointer;
  transition: all var(--speed);
}
.seg button:hover { color: var(--text); }
.seg button.selected {
  background: linear-gradient(180deg, var(--accent-2), var(--accent));
  color: #fff;
  box-shadow: 0 1px 8px -2px var(--accent-glow);
}

/* ----------------------------- Prompts ----------------------------- */

.toolbar { display: flex; align-items: center; gap: 10px; margin-bottom: 16px; flex-wrap: wrap; }
.toolbar-spacer { flex: 1; }
.muted { color: var(--text-faint); font-size: 12px; }

.prompts-list { display: flex; flex-direction: column; gap: 10px; }
.prompt-card {
  background: linear-gradient(180deg, var(--bg-raised), #17171a);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 13px 15px;
  transition: border-color var(--speed);
}
.prompt-card:focus-within { border-color: var(--border-strong); }
.prompt-card .prompt-head { display: flex; align-items: center; gap: 8px; margin-bottom: 9px; }
.prompt-index { font-size: 11px; color: var(--text-faint); font-weight: 700; font-family: var(--mono); }
.prompt-badges { display: flex; gap: 5px; flex-wrap: wrap; }
.badge {
  font-size: 10px; padding: 2px 8px; border-radius: 99px;
  background: var(--bg-panel); border: 1px solid var(--border); color: var(--text-dim);
}
.prompt-head .grow { flex: 1; }
.prompt-card textarea.prompt-text { font-family: inherit; min-height: 42px; }
.prompt-extra { margin-top: 9px; display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.prompt-extra .span-2 { grid-column: span 2; }
.prompt-extra input, .prompt-extra textarea { font-size: 12.5px; }
.link-btn { background: none; border: none; color: var(--text-faint); font-size: 12px; cursor: pointer; padding: 2px 6px; border-radius: 5px; transition: color var(--speed); }
.link-btn:hover { color: var(--accent-text); }
