  display: flex; align-items: center; gap: 10px;
  background: var(--bg-input); border: 1px solid var(--border-soft);
  border-radius: 9px; padding: 9px 12px; font-size: 12.5px;
}
.run-row .prompt-preview { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-dim); }
.chip {
  font-size: 10px; font-weight: 700; padding: 2px 9px; border-radius: 99px;
  text-transform: uppercase; letter-spacing: 0.5px;
}
.chip.queued { background: var(--bg-panel); color: var(--text-faint); border: 1px solid var(--border); }
.chip.running, .chip.starting { background: rgba(242, 92, 26, 0.15); color: var(--accent-text); border: 1px solid rgba(242, 92, 26, 0.3); }
.chip.completed { background: rgba(62, 207, 142, 0.12); color: var(--green); border: 1px solid rgba(62, 207, 142, 0.3); }
.chip.failed, .chip.stopped { background: rgba(239, 90, 95, 0.12); color: var(--red); border: 1px solid rgba(239, 90, 95, 0.3); }
.run-row .meta { color: var(--text-faint); font-size: 11.5px; white-space: nowrap; max-width: 40%; overflow: hidden; text-overflow: ellipsis; }

@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.45; } }
.pulsing { animation: pulse 1.4s ease-in-out infinite; }

/* ----------------------------- Terminal window ----------------------------- */

.term-window {
  flex: 1;
  display: flex; flex-direction: column;
  background: #101013;
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 12px 40px -12px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255,255,255,0.02) inset;
  min-height: 420px;
}

.term-titlebar {
  display: flex; align-items: center; gap: 12px;
  padding: 9px 14px;
  background: linear-gradient(180deg, #1d1d22, #18181c);
  border-bottom: 1px solid var(--border-soft);
}
.term-lights { display: flex; gap: 7px; }
.term-lights span { width: 11px; height: 11px; border-radius: 50%; }
.term-lights span:nth-child(1) { background: #ff5f57; }
.term-lights span:nth-child(2) { background: #febc2e; }
.term-lights span:nth-child(3) { background: #28c840; }
.term-title {
  flex: 1; display: flex; align-items: center; gap: 8px; justify-content: center;
  font-family: var(--mono); font-size: 12px; color: var(--text-dim);
  min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.term-actions { display: flex; gap: 7px; }

.term-banner {
  padding: 8px 14px;
  background: rgba(242, 92, 26, 0.1);
  border-bottom: 1px solid rgba(242, 92, 26, 0.25);
  color: var(--accent-text);
  font-size: 12.5px;
}
.term-banner.success { background: rgba(62, 207, 142, 0.08); border-color: rgba(62, 207, 142, 0.3); color: var(--green); }
.term-banner.error { background: rgba(239, 90, 95, 0.08); border-color: rgba(239, 90, 95, 0.3); color: var(--red); }

.term-body { flex: 1; padding: 8px 4px 4px 10px; min-height: 0; }
.term-body .xterm { height: 100%; }

.term-statusbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 6px 14px;
  background: #141418;
  border-top: 1px solid var(--border-soft);
  font-size: 11.5px; color: var(--text-faint);
  font-family: var(--mono);
}

.status-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--text-faint); flex-shrink: 0; }
.status-dot.ready, .status-dot.idle, .status-dot.live { background: var(--green); box-shadow: 0 0 8px rgba(62, 207, 142, 0.7); }
.status-dot.running, .status-dot.starting, .status-dot.saving { background: var(--accent); box-shadow: 0 0 8px var(--accent-glow); animation: pulse 1.2s infinite; }
.status-dot.error, .status-dot.discarded { background: var(--red); }
.status-dot.exited { background: var(--yellow); }
.status-dot.finished { background: var(--green); }

/* ----------------------------- Chat (chat provider + previews) ----------------------------- */

.chat-window {
  flex: 1; display: flex; flex-direction: column;
  background: var(--bg-raised);
  border: 1px solid var(--border-soft);
  border-radius: 14px;
  overflow: hidden;
  min-height: 420px;
}
.chat-scroll {
  flex: 1; overflow-y: auto;
  display: flex; flex-direction: column; gap: 10px;
  padding: 16px 14px;
}

.msg { max-width: 86%; animation: viewIn 0.18s ease; }
.msg .msg-body {
  border-radius: 13px; padding: 10px 14px;
  white-space: pre-wrap; word-break: break-word;
  font-size: 13.5px;
}
.msg.user { align-self: flex-end; }
.msg.user .msg-body {
  background: linear-gradient(180deg, var(--accent-2), var(--accent));
  color: #fff; border-bottom-right-radius: 5px;
  box-shadow: 0 2px 10px -3px var(--accent-glow);
}
.msg.assistant { align-self: flex-start; }
.msg.assistant .msg-body { background: var(--bg-panel); border: 1px solid var(--border-soft); border-bottom-left-radius: 5px; }

.msg.block { align-self: stretch; max-width: 100%; }
.msg.block details {
  background: var(--bg-raised); border: 1px solid var(--border-soft);
  border-radius: 10px; overflow: hidden;
}
.msg.block summary {
  cursor: pointer; padding: 8px 13px; font-size: 12px; color: var(--text-dim);
  display: flex; align-items: center; gap: 8px; user-select: none; list-style: none;
}
.msg.block summary::-webkit-details-marker { display: none; }
.msg.block summary .tool-name { color: var(--accent-text); font-family: var(--mono); font-weight: 600; }
.msg.block summary .muted { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.msg.block .block-body {
  border-top: 1px solid var(--border-soft);
  padding: 10px 13px; font-family: var(--mono); font-size: 12px;
  white-space: pre-wrap; word-break: break-word;
  color: var(--text-dim); max-height: 320px; overflow-y: auto;
}
.msg.thinking summary { color: var(--text-faint); font-style: italic; }

.msg.status-line { align-self: center; color: var(--text-faint); font-size: 12px; text-align: center; }
.msg.error-line {
  align-self: stretch; max-width: 100%;
  background: rgba(239, 90, 95, 0.08); border: 1px solid rgba(239, 90, 95, 0.35);
  color: #ff9a9e; border-radius: 10px; padding: 10px 14px;
  font-size: 12.5px; white-space: pre-wrap; word-break: break-word;
}
.msg.saved-line {
  align-self: center; color: var(--green); font-size: 12.5px;
  background: rgba(62, 207, 142, 0.08); border: 1px solid rgba(62, 207, 142, 0.3);
  border-radius: 99px; padding: 6px 16px;
}

.typing { align-self: flex-start; color: var(--text-faint); font-size: 12.5px; padding: 4px 10px; }
.typing .dots span { animation: pulse 1.2s infinite; display: inline-block; }
.typing .dots span:nth-child(2) { animation-delay: 0.2s; }
.typing .dots span:nth-child(3) { animation-delay: 0.4s; }

.composer {
  display: flex; gap: 9px; align-items: flex-end;
  padding: 12px;
  border-top: 1px solid var(--border-soft);
  background: var(--bg-input);
}
.composer textarea { flex: 1; max-height: 160px; border-radius: 10px; }

.row-actions { margin-top: 16px; display: flex; align-items: center; gap: 12px; }

/* ----------------------------- Output ----------------------------- */

.output-layout { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 14px; align-items: start; }
.trace-list { padding: 8px; max-height: 72vh; overflow-y: auto; }
.trace-item {
  width: 100%; text-align: left; background: none; border: none; color: var(--text);
  font: inherit; padding: 10px 12px; border-radius: 9px; cursor: pointer;
  display: flex; flex-direction: column; gap: 3px;
  transition: background var(--speed);
}
.trace-item:hover { background: var(--bg-panel); }
.trace-item.selected { background: var(--accent-soft); box-shadow: inset 2px 0 0 var(--accent); }
.trace-item .trace-name { font-size: 12px; font-family: var(--mono); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.trace-item.selected .trace-name { color: var(--accent-text); }
.trace-item .trace-meta { font-size: 11px; color: var(--text-faint); }
.trace-preview { max-height: 72vh; overflow-y: auto; display: flex; flex-direction: column; gap: 10px; }
.trace-preview .msg { max-width: 100%; }
.preview-head { display: flex; align-items: center; gap: 10px; padding-bottom: 8px; border-bottom: 1px solid var(--border-soft); }
.preview-head .badge { text-transform: capitalize; border-color: var(--accent-glow); color: var(--accent-text); }
.preview-head .muted { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: var(--mono); font-size: 11.5px; }

@media (max-width: 860px) {
  .main { padding: 22px 18px 80px; }
  .form-grid { grid-template-columns: 1fr; }
  .field.span-2 { grid-column: span 1; }
  .output-layout { grid-template-columns: 1fr; }
  .trace-list { max-height: 32vh; }
}

/* ----------------------------- Toast ----------------------------- */

#toast {
  position: fixed; bottom: 26px; left: 50%; transform: translateX(-50%);
  background: var(--bg-panel); border: 1px solid var(--border-strong);
  color: var(--text); padding: 11px 20px; border-radius: 11px;
  font-size: 13px; z-index: 100;
  box-shadow: 0 10px 32px rgba(0, 0, 0, 0.5);
  animation: toastIn 0.2s ease;
}
@keyframes toastIn {
  from { opacity: 0; transform: translate(-50%, 8px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}
#toast.error { border-color: var(--red); color: #ff9a9e; }
#toast.success { border-color: var(--green); }
